# Vision dans la liste des écrans de veille de Windows : un petit programme sans fenêtre, compilé sur place.
# Lancé par Windows (« /s »), il demande la veille à la fenêtre Vision de la session et attend qu'elle se
# referme. « /c » ouvre les réglages de Vision ; « /p » (l'aperçu miniature) ne fait rien.
$script:ScrVersion = '1'
$script:ScrSource = @'
using System;
using System.Threading;
[assembly: System.Reflection.AssemblyTitle("Vision")]
[assembly: System.Reflection.AssemblyProduct("Vision")]
[assembly: System.Reflection.AssemblyDescription("Ecran de veille Vision")]
static class VisionEcranDeVeille {
    static bool Signal(string nom) {
        try { using (EventWaitHandle e = EventWaitHandle.OpenExisting(nom)) { e.Set(); return true; } } catch { return false; }
    }
    [STAThread]
    static int Main(string[] a) {
        string m = a.Length > 0 ? a[0].ToLowerInvariant() : "/c";
        if (m.StartsWith("/p") || m.StartsWith("/a")) return 0;
        if (m.StartsWith("/c")) { Signal("Local\\VisionVeilleReglages"); return 0; }
        if (!Signal("Local\\VisionVeilleDemande")) return 0;
        try {
            using (EventWaitHandle ouverte = EventWaitHandle.OpenExisting("Local\\VisionVeilleOuverte")) {
                int attente = 0;
                while (!ouverte.WaitOne(0) && attente < 60) { Thread.Sleep(250); attente++; }
                while (ouverte.WaitOne(0)) { Thread.Sleep(250); }
            }
        } catch { }
        return 0;
    }
}
