function Install-EcranDeVeille {
    # Une tentative par démarrage de l'agent : un refus (antivirus, droits) ne se rejoue pas en boucle.
    if ($script:ScrEssaye) { return }
    $script:ScrEssaye = $true
    try {
        $cible = Join-Path $env:SystemRoot 'System32\Vision.scr'
        $marque = Join-Path (Split-Path $ConfigPath -Parent) 'vision-scr.txt'
        $fait = ''
        if (Test-Path $marque) { $fait = ([string](Get-Content $marque -Raw -ErrorAction SilentlyContinue)).Trim() }
        if ((Test-Path $cible) -and $fait -eq $script:ScrVersion) { return }
        $tmp = Join-Path $env:TEMP ('vision-scr-{0}.exe' -f [guid]::NewGuid().ToString('N'))
        Add-Type -TypeDefinition $script:ScrSource -OutputAssembly $tmp -OutputType WindowsApplication -ErrorAction Stop
        Copy-Item -Path $tmp -Destination $cible -Force -ErrorAction Stop
        Remove-Item $tmp -Force -ErrorAction SilentlyContinue
        Set-Content -Path $marque -Value $script:ScrVersion -Encoding ASCII
        Write-Journal "Ecran de veille Vision installe dans Windows."
    } catch {
        Write-Journal "Ecran de veille Vision non installe dans Windows : $_" 'WARN'
    }
}

